package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
import static com.oms.order.service.ExchangeService.object;

/** Indexed, tenant-scoped list queries. A matching member selects its complete package/document. */
@Service public class ReturnQueryService {
    @Resource OrderRepository repository;
    @Resource ReturnQueryProjection projection;
    @Resource OrderCatalog catalog;
    @Resource ReturnQueryClient warehouse;
    static final Set<String> WAREHOUSE_FILTERS=new HashSet<>(Arrays.asList("","UNSENT","SENDING","ACCEPTED","FAILED","UNKNOWN","CANCEL_PENDING","CANCEL_REJECTED","CANCELED","LAST_FAILED","WAIT_ALLOCATION","DIFFERENCE"));
    private static Map<String,Object> readObject(Object raw){Map<String,Object> value=object(raw);return value==null?Collections.emptyMap():value;}
    static final Set<String> VIEWS=new HashSet<>(Arrays.asList("TASK","PARCEL","DOCUMENT"));
    static final Set<String> NUMBER_TYPES=new HashSet<>(Arrays.asList("ANY","OWNER","PLATFORM_AFTERSALE","ORDER","TID","OID","SHIPMENT","WAYBILL","OUTBOUND_WAYBILL","PARCEL","DOCUMENT"));
    static final Map<String,List<String>> BUCKETS=new LinkedHashMap<>();static {BUCKETS.put("",Collections.emptyList());BUCKETS.put("WAIT_LOGISTICS",Arrays.asList("WAIT_LOGISTICS"));BUCKETS.put("WAIT_DISPATCH",Arrays.asList("WAIT_DISPATCH","COLLECT"));BUCKETS.put("WAIT_RECEIVE",Arrays.asList("WAIT_RECEIVE","PARTIAL"));BUCKETS.put("WAIT_POST",Arrays.asList("WAIT_POST"));BUCKETS.put("NEED_CHECK",Arrays.asList("NEED_CHECK"));BUCKETS.put("DONE",Arrays.asList("DONE"));BUCKETS.put("STOPPED",Arrays.asList("STOPPED"));}
    static String marks(Collection<?> items){return String.join(",",Collections.nCopies(items.size(),"?"));}
    static List<String> numbers(String raw){Set<String> result=new LinkedHashSet<>();for(String n:raw.trim().split("[\\s,，;；]+"))if(!n.isEmpty()){require(n.length()<=128,"单号最多128个字符");result.add(n);}require(result.size()<=100,"一次最多查询100个完整单号");return new ArrayList<>(result);}
    static int integer(String s,int fallback){if(s==null||s.isEmpty())return fallback;try{return Integer.parseInt(s);}catch(Exception e){throw new IllegalArgumentException("分页参数无效");}}
    private void validate(Map<String,String> q){
        require(WAREHOUSE_FILTERS.contains(q.getOrDefault("warehouse","")),"仓库交互筛选无效");
        require(VIEWS.contains(q.getOrDefault("view","TASK")),"退货视图无效");require(NUMBER_TYPES.contains(q.getOrDefault("numberType","ANY")),"单号类型无效");require(BUCKETS.containsKey(q.getOrDefault("stage","")),"进度筛选无效");require(Arrays.asList("","SINGLE","MERGED","REFUND_MULTI","EXCHANGE_MULTI","MIXED").contains(q.getOrDefault("merge","")),"合包类型无效");require(Arrays.asList("","REFUND","EXCHANGE").contains(q.getOrDefault("kind","")),"售后来源无效");require(Arrays.asList("","PURCHASE","GIFT").contains(q.getOrDefault("itemKind","")),"商品身份无效");require(Arrays.asList("","RETURN","INTERCEPT","REFUSAL").contains(q.getOrDefault("mode","")),"退回方式无效");require(q.getOrDefault("product","").length()<=128,"商品检索最多128个字符");numbers(q.getOrDefault("number",""));int page=integer(q.get("pageNum"),1),size=integer(q.get("pageSize"),20);require(page>=1&&page<=10000&&size>=1&&size<=50,"每页最多50条，请检查分页参数");for(String k:Arrays.asList("channelId"))if(!q.getOrDefault(k,"").isEmpty())require(q.get(k).matches("[1-9][0-9]{0,18}"),"店铺编号无效");require(q.getOrDefault("store","").length()<=64,"仓库条件过长");
    }
    static String statusSql(String alias,String view){String a=alias+".";return "CASE WHEN MAX("+a+"needs_check)>0 OR MAX("+a+"pending_count)>0 OR MIN("+a+"quantity_known)=0"+("TASK".equals(view)?"":" OR MAX("+a+"expected_members)>COUNT(DISTINCT "+a+"source_key)")+" THEN 'NEED_CHECK' WHEN SUM(GREATEST("+a+"accepted_quantity-"+a+"posted_quantity,0))>0 THEN 'WAIT_POST' WHEN MAX("+a+"active)=0 AND SUM(GREATEST("+a+"quantity-"+a+"posted_quantity-"+a+"waived_quantity,0))>0 THEN 'STOPPED' WHEN SUM("+a+"quantity)>0 AND SUM(GREATEST("+a+"quantity-"+a+"posted_quantity-"+a+"waived_quantity,0))=0 THEN 'DONE' WHEN SUM("+a+"accepted_quantity)>0 THEN 'PARTIAL' WHEN MAX("+a+"dispatched)>0 THEN 'WAIT_RECEIVE' WHEN MAX("+a+"dispatch_after)>NOW() THEN 'COLLECT' WHEN MAX("+a+"waybill)='' THEN 'WAIT_LOGISTICS' ELSE 'WAIT_DISPATCH' END";}
    private Query grouped(String c,Map<String,String> q,boolean exactGroup){
        String view=q.getOrDefault("view","TASK"),where="r.company_code=? AND r.view_kind=?";List<Object> args=new ArrayList<>(Arrays.asList(c,view)),numberArgs=new ArrayList<>();String selectionFrom="oms_return_query_row r";List<String> ns=numbers(q.getOrDefault("number",""));
        if(exactGroup){where+=" AND r.group_key=?";args.add(q.get("key"));}else{
            String warehouse=q.getOrDefault("warehouse","");if("LAST_FAILED".equals(warehouse))where+=" AND r.interaction_result='FAILED'";else if("DIFFERENCE".equals(warehouse))where+=" AND r.receipt_difference>0";else if("WAIT_ALLOCATION".equals(warehouse))where+=" AND r.pending_count>0";else if(!warehouse.isEmpty()){where+=" AND r.warehouse_state=?";args.add(warehouse);}
            for(String[] filter:new String[][]{{"channelId","channel_id"},{"store","store_code"},{"kind","owner_kind"},{"mode","return_mode"}})if(!q.getOrDefault(filter[0],"").isEmpty()){where+=" AND r."+filter[1]+"=?";args.add(q.get(filter[0]));}
            String item=q.getOrDefault("itemKind","");if(!item.isEmpty()){where+=" AND r.is_gift=?";args.add("GIFT".equals(item)?1:0);}if("1".equals(q.get("refundOnly")))where+=" AND r.refund_only=1";
            if(!q.getOrDefault("product","").isEmpty()){where+=" AND (r.sku_sn LIKE ? ESCAPE '!' OR r.goods_name LIKE ? ESCAPE '!')";String value="%"+q.get("product").replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.add(value);args.add(value);}
            if(!ns.isEmpty()){String lookup="SELECT DISTINCT n.group_key FROM oms_return_query_number n WHERE n.company_code=? AND n.view_kind=? AND n.number_value IN ("+marks(ns)+")";numberArgs.add(c);numberArgs.add(view);numberArgs.addAll(ns);String nt=q.getOrDefault("numberType","ANY");if(!"ANY".equals(nt)){lookup+=" AND n.number_type=?";numberArgs.add(nt);}selectionFrom="("+lookup+") matched STRAIGHT_JOIN oms_return_query_row r ON r.group_key=matched.group_key";}
            String from=q.getOrDefault("from",""),to=q.getOrDefault("to","");if(from.isEmpty()&&to.isEmpty()&&ns.isEmpty()){from=LocalDate.now().minusDays(30).toString();to=LocalDate.now().toString();}
            try{if(!from.isEmpty()||!to.isEmpty()){require(!from.isEmpty()&&!to.isEmpty(),"请完整选择查询日期");LocalDate start=LocalDate.parse(from),end=LocalDate.parse(to);require(!end.isBefore(start)&&!end.isAfter(start.plusDays(93)),"时间范围最多93天");where+=" AND r.create_time>=? AND r.create_time<?";args.add(start.toString()+" 00:00:00");args.add(end.plusDays(1).toString()+" 00:00:00");}}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("查询日期格式无效");}
        }
        // Apply lookup predicates only to group selection. All source quantities remain in the outer aggregate.
        String sql="SELECT a.group_key,MIN(a.create_time) create_time,MAX(a.sync_time) sync_time,MAX(a.channel_id) channel_id,COUNT(DISTINCT a.channel_id) channel_count,MAX(a.store_code) store_code,MAX(a.real_store_code) real_store_code,MAX(a.owner_code) owner_code,MAX(a.parcel_sn) parcel_sn,MAX(a.parcel_key) parcel_key,MAX(a.return_sn) return_sn,MAX(a.ticket_id) ticket_id,MAX(a.carrier) carrier,MAX(a.waybill) waybill,MAX(a.dispatch_after) dispatch_after,MAX(a.pending_count) pending_count,MAX(a.expected_members) expected_members,COUNT(DISTINCT a.source_key) source_count,COUNT(DISTINCT CONCAT(a.owner_kind,':',a.owner_id)) owner_count,COUNT(DISTINCT IF(a.owner_kind='REFUND',a.owner_id,NULL)) refund_count,COUNT(DISTINCT IF(a.owner_kind='EXCHANGE',a.owner_id,NULL)) exchange_count,MAX(a.is_gift) has_gift,MAX(a.refund_only) refund_only,MAX(a.message) message,"+statusSql("a",view)+" stage FROM oms_return_query_row a JOIN (SELECT r.group_key FROM "+selectionFrom+" WHERE "+where+" GROUP BY r.group_key) selected ON selected.group_key=a.group_key WHERE a.company_code=? AND a.view_kind=? GROUP BY a.group_key";if(!numberArgs.isEmpty()){List<Object> ordered=new ArrayList<>(numberArgs);ordered.addAll(args);args=ordered;}args.add(c);args.add(view);
        String merge=q.getOrDefault("merge","");if(!merge.isEmpty()){String having="";switch(merge){case "SINGLE":having="COUNT(DISTINCT a.source_key)=1";break;case "MERGED":having="COUNT(DISTINCT a.source_key)>1";break;case "REFUND_MULTI":having="COUNT(DISTINCT IF(a.owner_kind='REFUND',a.owner_id,NULL))>1 AND COUNT(DISTINCT IF(a.owner_kind='EXCHANGE',a.owner_id,NULL))=0";break;case "EXCHANGE_MULTI":having="COUNT(DISTINCT IF(a.owner_kind='EXCHANGE',a.owner_id,NULL))>1 AND COUNT(DISTINCT IF(a.owner_kind='REFUND',a.owner_id,NULL))=0";break;case "MIXED":having="COUNT(DISTINCT IF(a.owner_kind='EXCHANGE',a.owner_id,NULL))>0 AND COUNT(DISTINCT IF(a.owner_kind='REFUND',a.owner_id,NULL))>0";}sql+=" HAVING "+having;}
        return new Query(sql,args);
    }
    public Map<String,Object> list(String c,Map<String,String> q,boolean export){
        validate(q);Query query=grouped(c,q,false);Map<String,Object> sync=projection.refresh(c);List<Map<String,Object>> counts=repository.db().query("SELECT stage,COUNT(*) total FROM ("+query.sql+") totals GROUP BY stage",ROW,query.args.toArray());Map<String,Long> buckets=new LinkedHashMap<>();for(String k:BUCKETS.keySet())buckets.put(k,0L);for(Map<String,Object> row:counts){long n=number(row,"total");buckets.put("",buckets.get("")+n);for(String k:BUCKETS.keySet())if(BUCKETS.get(k).contains(text(row,"stage")))buckets.put(k,buckets.get(k)+n);}
        String stage=q.getOrDefault("stage","");long total=buckets.get(stage);require(!export||total<=2000,"查询结果超过2000条，请缩小条件后导出");List<Object> args=new ArrayList<>(query.args);String sql="SELECT * FROM ("+query.sql+") g";if(!stage.isEmpty()){sql+=" WHERE g.stage IN ("+marks(BUCKETS.get(stage))+")";args.addAll(BUCKETS.get(stage));}int size=export?2000:integer(q.get("pageSize"),20),offset=export?0:(integer(q.get("pageNum"),1)-1)*size;sql+=" ORDER BY create_time DESC,group_key DESC LIMIT ? OFFSET ?";args.add(size);args.add(offset);
        List<Map<String,Object>> rows=repository.db().query(sql,ROW,args.toArray());decorate(c,q,rows,false);return map("rows",rows,"total",total,"buckets",buckets,"synchronization",sync);
    }
    public Map<String,Object> detail(String c,String view,String key,Map<String,String> search){require(VIEWS.contains(view)&&key!=null&&!key.isEmpty()&&key.length()<=160,"退货查询记录无效");Map<String,Object> sync="DOCUMENT".equals(view)?projection.refresh(c):Collections.emptyMap();if(sync==null)sync=Collections.emptyMap();Map<String,String> q=new HashMap<>();q.put("view",view);q.put("key",key);Query query=grouped(c,q,true);List<Map<String,Object>> rows=repository.db().query(query.sql,ROW,query.args.toArray());if(rows.isEmpty()&&"DOCUMENT".equals(view)&&(Boolean.TRUE.equals(sync.get("updating"))||!text(sync,"warning").isEmpty()))return map("loading",true,"synchronization",sync);require(rows.size()==1,"退货记录不存在或不属于当前公司");q.putAll(search);q.put("view",view);decorate(c,q,rows,true);rows.get(0).put("synchronization",sync);return rows.get(0);}
    private void decorate(String c,Map<String,String> q,List<Map<String,Object>> rows,boolean detail){
        if(rows.isEmpty())return;List<String> keys=new ArrayList<>();Map<String,Map<String,Object>> by=new LinkedHashMap<>();for(Map<String,Object> r:rows){String key=text(r,"group_key");keys.add(key);by.put(key,r);r.put("members",new ArrayList<>());r.put("units",new LinkedHashMap<>());r.put("matched_count",0);r.put("warehouse_documents",new LinkedHashMap<>());}
        List<Object> args=new ArrayList<>(Arrays.asList(c,q.getOrDefault("view","TASK")));args.addAll(keys);int limit=detail?5001:20001;List<Map<String,Object>> members=repository.db().query("SELECT * FROM oms_return_query_row WHERE company_code=? AND view_kind=? AND group_key IN ("+marks(keys)+") ORDER BY owner_kind,owner_id,source_key,part_key LIMIT "+limit,ROW,args.toArray());require(members.size()<limit,"关联来源超过查询上限，请缩小范围");
        Set<String> hits=new HashSet<>();List<String> ns=numbers(q.getOrDefault("number",""));if(!ns.isEmpty()){List<Object> lookup=new ArrayList<>(args);lookup.addAll(ns);String sql="SELECT DISTINCT group_key,owner_kind,owner_id FROM oms_return_query_number WHERE company_code=? AND view_kind=? AND group_key IN ("+marks(keys)+") AND number_value IN ("+marks(ns)+")";if(!"ANY".equals(q.getOrDefault("numberType","ANY"))){sql+=" AND number_type=?";lookup.add(q.get("numberType"));}for(Map<String,Object> n:repository.db().query(sql,ROW,lookup.toArray()))hits.add(n.get("group_key")+"/"+n.get("owner_kind")+"/"+n.get("owner_id"));}
        if(detail)enrichMembers(c,members);
        for(Map<String,Object> member:members){Map<String,Object> row=by.get(text(member,"group_key"));boolean matched=hits.contains(member.get("group_key")+"/"+member.get("owner_kind")+"/"+member.get("owner_id"));member.put("matched",matched);if(matched)row.put("matched_count",number(row,"matched_count")+1);Map<String,Object> w=readObject(member.get("snapshot"));if(detail)member.put("warehouse",w);if(!text(w,"return_sn").isEmpty())((Map<String,Map<String,Object>>)row.get("warehouse_documents")).put(text(w,"return_sn"),w);member.remove("snapshot");((List<Map<String,Object>>)row.get("members")).add(member);Map<String,Map<String,Object>> units=(Map<String,Map<String,Object>>)row.get("units");Map<String,Object> u=units.computeIfAbsent(text(member,"unit"),k->map("unit",k,"quantity",0L,"accepted_quantity",0L,"posted_quantity",0L,"waived_quantity",0L,"remaining_quantity",0L,"unposted_quantity",0L,"unknown",0L));for(String k:Arrays.asList("quantity","accepted_quantity","posted_quantity","waived_quantity"))u.put(k,number(u,k)+number(member,k));u.put("remaining_quantity",number(u,"remaining_quantity")+(number(member,"active")==1?Math.max(0,number(member,"quantity")-number(member,"accepted_quantity")-number(member,"waived_quantity")):0));u.put("unposted_quantity",number(u,"unposted_quantity")+Math.max(0,number(member,"accepted_quantity")-number(member,"posted_quantity")));if(number(member,"quantity_known")==0)u.put("unknown",number(u,"unknown")+1);}
        for(Map<String,Object> row:rows){List<Map<String,Object>> docs=new ArrayList<>(((Map<String,Map<String,Object>>)row.get("warehouse_documents")).values());docs.sort((a,b)->Long.compare(number(readObject(b.get("interaction")),"id"),number(readObject(a.get("interaction")),"id")));row.put("warehouse_documents",docs);row.put("latest_interaction",docs.isEmpty()?Collections.emptyMap():readObject(docs.get(0).get("interaction")));row.put("units",new ArrayList<>(((Map<?,?>)row.get("units")).values()));row.put("view",q.getOrDefault("view","TASK"));row.put("incomplete",!"TASK".equals(row.get("view"))&&number(row,"expected_members")>number(row,"source_count"));if(!detail){List<Map<String,Object>> all=(List<Map<String,Object>>)row.get("members");Map<String,Map<String,Object>> products=new LinkedHashMap<>();for(Map<String,Object> m:all){String identity=text(m,"sku_sn")+"/"+text(m,"unit");Map<String,Object> p=products.get(identity);if(p==null){p=new LinkedHashMap<>(m);p.put("quantity",0L);p.put("is_gift",0L);products.put(identity,p);}p.put("quantity",number(p,"quantity")+number(m,"quantity"));p.put("is_gift",Math.max(number(p,"is_gift"),number(m,"is_gift")));}row.put("product_count",products.size());row.put("products",new ArrayList<>(new ArrayList<>(products.values()).subList(0,Math.min(3,products.size()))));row.put("members",new ArrayList<>(all.subList(0,Math.min(3,all.size()))));}}
    }
    public Map<String,Object> catalog(String c){return map("channels",catalog.channels(c),"warehouses",catalog.warehouses(c));}
    private void enrichMembers(String c,List<Map<String,Object>> members){
        if(catalog==null)return;Set<String> skus=new LinkedHashSet<>();for(Map<String,Object> m:members)if(!text(m,"sku_sn").isEmpty())skus.add(text(m,"sku_sn"));Map<String,List<Map<String,Object>>> products=Collections.emptyMap();
        try{if(!skus.isEmpty()&&skus.size()<=500)products=catalog.goods(c,new ArrayList<>(skus));}catch(RuntimeException unavailable){org.slf4j.LoggerFactory.getLogger(ReturnQueryService.class).debug("Return product specification lookup unavailable for {}",c);}
        for(Map<String,Object> m:members){List<Map<String,Object>> matches=products.getOrDefault(text(m,"sku_sn"),Collections.emptyList());if(matches.size()==1){Map<String,Object> g=matches.get(0);m.put("spec_name",(text(g,"color_name")+" "+text(g,"size_name")).trim());if(text(m,"goods_name").isEmpty())m.put("goods_name",g.get("goods_name"));}}
        for(String kind:Arrays.asList("REFUND","EXCHANGE")){Set<Long> ids=new LinkedHashSet<>();for(Map<String,Object> m:members)if(kind.equals(m.get("owner_kind")))ids.add(number(m,"source_id"));if(ids.isEmpty())continue;
            boolean refund="REFUND".equals(kind);String from=refund?"oms_refund_return_plan r":"oms_exchange r",line=refund?"r.shipment_line_id":"r.source_shipment_line_id";
            List<Object> a=new ArrayList<>(Arrays.asList(c));a.addAll(ids);Map<Long,Map<String,Object>> by=new HashMap<>();
            for(Map<String,Object> r:repository.db().query("SELECT r.id,sl.goods_name,ol.goods_name sale_name,ol.stocked_bundle_snapshot,b.goods_name parent_name,b.business_type parent_type FROM "+from+" LEFT JOIN oms_order_shipment_line sl ON sl.company_code=r.company_code AND sl.id="+line+" LEFT JOIN oms_order_line ol ON ol.company_code=sl.company_code AND ol.id=sl.order_line_id LEFT JOIN oms_order_bundle b ON b.company_code=ol.company_code AND b.id=ol.bundle_id WHERE r.company_code=? AND r.id IN ("+marks(ids)+")",ROW,a.toArray()))by.put(number(r,"id"),r);
            for(Map<String,Object> m:members)if(kind.equals(m.get("owner_kind"))){Map<String,Object> r=by.get(number(m,"source_id"));if(r==null)continue;if(!text(r,"goods_name").isEmpty())m.put("goods_name",r.get("goods_name"));if(!text(r,"parent_name").isEmpty())m.put("sales_parent",("LUCKY_BAG".equals(r.get("parent_type"))?"福袋组成 · ":"套装组成 · ")+text(r,"parent_name"));else if(r.get("stocked_bundle_snapshot")!=null)m.put("sales_parent","整套入库 · "+text(r,"sale_name"));}
        }
    }
    public Map<String,Object> document(String c,String sn,String section,int page,int size){require(sn!=null&&!sn.startsWith("RSL")&&sn.length()<=64,"请提供实际退货入库单号");require(Arrays.asList("SUMMARY","LINES","RECEIPTS","REVIEWS").contains(section)&&page>=1&&page<=10000&&size>=1&&size<=50,"退货明细类型或分页无效");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_return_query_row WHERE company_code=? AND view_kind='DOCUMENT' AND group_key=?",Long.class,c,sn)>0,"实际入库单不存在或不属于当前公司");return data(warehouse.document(c,sn,section,page,size,com.ruoyi.common.core.constant.SecurityConstants.INNER));}
    private static class Query {final String sql;final List<Object> args;Query(String sql,List<Object> args){this.sql=sql;this.args=args;}}
}
